   165→  public List<UInt64> computeColumnsForCustodyGroup(final UInt64 custodyGroup) {
   166→    if (custodyGroup.isGreaterThanOrEqualTo(specConfigFulu.getNumberOfCustodyGroups())) {
   167→      throw new IllegalArgumentException(
   168→          String.format(
   169→              "Custody group (%s) cannot exceed number of groups (%s)",
   170→              custodyGroup, specConfigFulu.getNumberOfCustodyGroups()));
   171→    }
   172→
   173→    final int columnsPerGroup =
   174→        specConfigFulu.getNumberOfColumns() / specConfigFulu.getNumberOfCustodyGroups();
   175→
   176→    return IntStream.range(0, columnsPerGroup)
   177→        .mapToLong(
   178→            i -> (long) specConfigFulu.getNumberOfCustodyGroups() * i + custodyGroup.intValue())
   179→        .mapToObj(UInt64::valueOf)
   180→        .toList();
   181→  }
