   183→  private UInt64 computeCustodyGroupIndex(final UInt256 nodeId) {
   184→    return bytesToUInt64(Hash.sha256(uint256ToBytes(nodeId)).slice(0, 8))
   185→        .mod(specConfigFulu.getNumberOfCustodyGroups());
   186→  }
   187→
   188→  public List<UInt64> getCustodyGroups(final UInt256 nodeId, final int custodyGroupCount) {
   189→    if (custodyGroupCount > specConfigFulu.getNumberOfCustodyGroups()) {
   190→      throw new IllegalArgumentException(
   191→          String.format(
   192→              "Custody group count (%s) cannot exceed number of groups (%s)",
   193→              custodyGroupCount, specConfigFulu.getNumberOfCustodyGroups()));
   194→    }
   195→
   196→    // Skip computation if all groups are custodied
   197→    if (custodyGroupCount == specConfigFulu.getNumberOfCustodyGroups()) {
   198→      return LongStream.range(0, custodyGroupCount).mapToObj(UInt64::valueOf).toList();
   199→    }
   200→
   201→    return Stream.iterate(nodeId, this::incrementByModule)
   202→        .map(this::computeCustodyGroupIndex)
   203→        .distinct()
   204→        .limit(custodyGroupCount)
   205→        .sorted()
   206→        .toList();
   207→  }
