   492→  public List<DataColumnSidecar> reconstructAllDataColumnSidecars(
   493→      final Collection<DataColumnSidecar> existingSidecars, final KZG kzg) {
   494→    if (existingSidecars.size() < (specConfigFulu.getNumberOfColumns() / 2)) {
   495→      final Optional<DataColumnSidecar> maybeSidecar = existingSidecars.stream().findAny();
   496→      throw new IllegalArgumentException(
   497→          String.format(
   498→              "Number of sidecars must be greater than or equal to the half of column count, slot: %s; columns: found %s, needed at least %d",
   499→              maybeSidecar.isPresent() ? maybeSidecar.get().getSlot().toString() : "unknown",
   500→              existingSidecars.size(),
   501→              specConfigFulu.getNumberOfColumns() / 2));
   502→    }
   503→    final List<List<MatrixEntry>> columnBlobEntries =
   504→        existingSidecars.stream()
   505→            .map(
   506→                sidecar ->
   507→                    IntStream.range(0, sidecar.getDataColumn().size())
   508→                        .mapToObj(
   509→                            rowIndex ->
   510→                                schemaDefinitionsFulu
   511→                                    .getMatrixEntrySchema()
   512→                                    .create(
   513→                                        sidecar.getDataColumn().get(rowIndex),
   514→                                        sidecar.getSszKZGProofs().get(rowIndex).getKZGProof(),
   515→                                        sidecar.getIndex(),
   516→                                        UInt64.valueOf(rowIndex)))
   517→                        .toList())
   518→            .toList();
   519→    final List<List<MatrixEntry>> blobColumnEntries = transpose(columnBlobEntries);
   520→    final List<List<MatrixEntry>> extendedMatrix = recoverMatrix(blobColumnEntries, kzg);
   521→    final DataColumnSidecar anyExistingSidecar =
   522→        existingSidecars.stream().findFirst().orElseThrow();
   523→    final SignedBeaconBlockHeader signedBeaconBlockHeader =
   524→        anyExistingSidecar.getSignedBeaconBlockHeader();
   525→    return constructDataColumnSidecars(
   526→        signedBeaconBlockHeader,
   527→        anyExistingSidecar.getSszKZGCommitments(),
   528→        anyExistingSidecar.getKzgCommitmentsInclusionProof().asListUnboxed(),
   529→        extendedMatrix);
   530→  }
