   607→  @Override
   608→  public List<Integer> computeProposerIndices(
   609→      final BeaconState state,
   610→      final UInt64 epoch,
   611→      final Bytes32 epochSeed,
   612→      final IntList activeValidatorIndices) {
   613→    final UInt64 startSlot = computeStartSlotAtEpoch(epoch);
   614→    return IntStream.range(0, specConfigFulu.getSlotsPerEpoch())
   615→        .mapToObj(
   616→            i -> {
   617→              final Bytes32 seed =
   618→                  Hash.sha256(
   619→                      Bytes.concat(
   620→                          epochSeed.toArray(), uint64ToBytes(startSlot.plus(i)).toArray()));
   621→              return computeProposerIndex(state, activeValidatorIndices, seed);
   622→            })
   623→        .toList();
   624→  }
   625→
   626→  // initialize_proposer_lookahead
   627→  public List<UInt64> initializeProposerLookahead(
   628→      final BeaconStateElectra state, final BeaconStateAccessorsFulu beaconAccessors) {
   629→    final UInt64 currentEpoch = computeEpochAtSlot(state.getSlot());
   630→    return IntStream.rangeClosed(0, specConfigFulu.getMinSeedLookahead())
   631→        .flatMap(
   632→            i ->
   633→                beaconAccessors.getBeaconProposerIndices(state, currentEpoch.plus(i)).stream()
   634→                    .mapToInt(Integer::intValue))
   635→        .mapToObj(UInt64::valueOf)
   636→        .toList();
   637→  }
   638→}
